head.b:skin:
/*
 * EditorialVocab 2026 Blogger Theme
 * Responsive editorial theme for daily vocabulary and exam preparation.
 */

:root {
  --page: #f6f8f4;
  --surface: #ffffff;
  --surface-soft: #eef5f1;
  --surface-warm: #fff7ed;
  --surface-alert: #fff1f0;
  --ink: #151a23;
  --ink-soft: #354052;
  --muted: #687386;
  --line: #d9e3dd;
  --line-strong: #bfcdc5;
  --teal: #0f766e;
  --teal-dark: #0a4f4b;
  --red: #b42318;
  --amber: #c66a00;
  --blue: #1d4ed8;
  --shadow: 0 18px 50px rgba(21, 26, 35, 0.10);
  --shadow-soft: 0 10px 28px rgba(21, 26, 35, 0.07);
  --font-body: 'Inter', Arial, sans-serif;
  --font-display: 'Libre Baskerville', Georgia, serif;
  --font-hindi: 'Hind', 'Inter', Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  min-height: 100%;
}

body {
  background: var(--page);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--teal);
  text-decoration: none;
}

a:hover,
a:focus {
  color: var(--red);
}

img {
  display: block;
  height: auto;
  max-width: 100%;
}

.skip-link {
  background: var(--ink);
  color: #ffffff;
  left: 16px;
  padding: 10px 14px;
  position: fixed;
  top: -60px;
  z-index: 999;
}

.skip-link:focus {
  top: 16px;
}

.menu-toggle {
  display: none;
}

.site-header {
  background: rgba(246, 248, 244, 0.94);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 80;
  backdrop-filter: blur(18px);
}

.header-inner {
  align-items: center;
  display: flex;
  gap: 24px;
  justify-content: space-between;
  margin: 0 auto;
  max-width: 1180px;
  min-height: 72px;
  padding: 12px 22px;
}

.brand {
  align-items: center;
  color: var(--ink);
  display: inline-flex;
  gap: 12px;
  min-width: 0;
}

.brand:hover,
.brand:focus {
  color: var(--ink);
}

.brand-mark {
  align-items: center;
  background: var(--ink);
  border-radius: 8px;
  color: #ffffff;
  display: inline-flex;
  flex: 0 0 42px;
  font-size: 13px;
  font-weight: 900;
  height: 42px;
  justify-content: center;
  letter-spacing: 0;
  width: 42px;
}

.brand-copy {
  display: grid;
  min-width: 0;
}

.brand-name {
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1.05;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.brand-tagline {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin-top: 4px;
  text-transform: uppercase;
}

.desktop-nav {
  align-items: center;
  display: flex;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.desktop-nav a {
  border-radius: 8px;
  color: var(--ink-soft);
  display: inline-flex;
  font-size: 13px;
  font-weight: 800;
  padding: 9px 11px;
}

.desktop-nav a:hover,
.desktop-nav a:focus {
  background: var(--surface-soft);
  color: var(--teal-dark);
}

.nav-trigger {
  align-items: center;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  cursor: pointer;
  display: none;
  flex: 0 0 42px;
  height: 42px;
  justify-content: center;
  position: relative;
  width: 42px;
}

.nav-trigger span,
.nav-trigger span:before,
.nav-trigger span:after {
  background: var(--ink);
  border-radius: 99px;
  content: '';
  display: block;
  height: 2px;
  position: absolute;
  transition: transform 0.2s ease, opacity 0.2s ease;
  width: 18px;
}

.nav-trigger span:before {
  transform: translateY(-6px);
}

.nav-trigger span:after {
  transform: translateY(6px);
}

.mobile-nav {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  box-shadow: var(--shadow-soft);
  display: none;
  left: 0;
  padding: 10px 22px 20px;
  position: fixed;
  right: 0;
  top: 72px;
  transform: translateY(-120%);
  transition: transform 0.25s ease;
  z-index: 70;
}

.mobile-nav a {
  align-items: center;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  display: flex;
  font-size: 15px;
  font-weight: 800;
  justify-content: space-between;
  padding: 14px 0;
}

.top-announcement,
.below-hero-layout,
.above-main-layout {
  margin: 0 auto;
  max-width: 1180px;
  padding: 0 22px;
}

.top-announcement {
  padding-top: 10px;
}

.layout-widget-zone .widget,
.header-layout-zone .widget,
.wide-layout-zone .widget,
.post-layout-zone .widget,
.sidebar-layout-zone .widget,
#sidebar-extra .widget,
.footer-widget-zone .widget {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow-soft);
  color: var(--ink);
  margin: 0 0 16px;
  overflow: hidden;
  padding: 16px;
}

.layout-widget-zone:empty,
.header-layout-zone:empty,
.wide-layout-zone:empty,
.post-layout-zone:empty,
.sidebar-layout-zone:empty,
#sidebar-extra:empty,
.footer-widget-zone:empty {
  display: none;
}

.top-announcement .widget {
  background: var(--ink);
  color: #ffffff;
  margin-bottom: 10px;
  text-align: center;
}

.top-announcement a,
.top-announcement .widget-title,
.top-announcement .widget-content {
  color: #ffffff;
}

.header-layout-zone {
  align-items: center;
  display: flex;
  flex: 0 1 240px;
  justify-content: flex-end;
  min-width: 0;
}

.header-layout-zone .widget {
  background: transparent;
  border: 0;
  box-shadow: none;
  margin: 0;
  max-width: 240px;
  padding: 0;
}

.header-layout-zone img {
  max-height: 46px;
  width: auto;
}

.hero-widget-zone {
  max-width: 790px;
}

.hero-widget-zone .widget {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 8px;
  color: #ffffff;
  margin-top: 22px;
  padding: 16px;
}

.hero-widget-zone a,
.hero-widget-zone .widget-title {
  color: #ffffff;
}

.below-hero-layout,
.above-main-layout {
  padding-top: 22px;
}

.wide-layout-zone .widget,
.post-layout-zone .widget {
  text-align: center;
}

.menu-toggle:checked ~ .site-header .nav-trigger span {
  background: transparent;
}

.menu-toggle:checked ~ .site-header .nav-trigger span:before {
  transform: rotate(45deg);
}

.menu-toggle:checked ~ .site-header .nav-trigger span:after {
  transform: rotate(-45deg);
}

.menu-toggle:checked ~ .mobile-nav {
  transform: translateY(0);
}

.hero {
  background-color: #18212c;
  background-image:
    linear-gradient(90deg, rgba(10, 18, 28, 0.86), rgba(10, 18, 28, 0.45)),
    url('https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=1600&q=80');
  background-position: center;
  background-size: cover;
  color: #ffffff;
  min-height: clamp(340px, 52vh, 520px);
}

.hero-inner {
  display: grid;
  gap: 28px;
  margin: 0 auto;
  max-width: 1180px;
  min-height: inherit;
  padding: clamp(48px, 8vw, 86px) 22px 42px;
}

.hero-copy {
  align-self: end;
  max-width: 790px;
}

.kicker {
  align-items: center;
  color: #d6fff8;
  display: inline-flex;
  font-size: 12px;
  font-weight: 900;
  gap: 8px;
  letter-spacing: 0.14em;
  margin: 0 0 18px;
  text-transform: uppercase;
}

.kicker:before {
  background: #f5b642;
  content: '';
  display: inline-block;
  height: 2px;
  width: 42px;
}

.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(38px, 6vw, 72px);
  letter-spacing: 0;
  line-height: 1.03;
  margin: 0;
  max-width: 830px;
}

.hero-summary {
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(16px, 2.2vw, 20px);
  font-weight: 500;
  line-height: 1.65;
  margin: 20px 0 0;
  max-width: 700px;
}

.hero-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}

.button {
  align-items: center;
  border: 1px solid transparent;
  border-radius: 8px;
  display: inline-flex;
  font-size: 14px;
  font-weight: 900;
  justify-content: center;
  line-height: 1;
  min-height: 44px;
  padding: 0 17px;
}

.button-primary {
  background: #ffffff;
  color: var(--ink);
}

.button-primary:hover,
.button-primary:focus {
  background: #e7fff9;
  color: var(--teal-dark);
}

.button-secondary {
  border-color: rgba(255, 255, 255, 0.45);
  color: #ffffff;
}

.button-secondary:hover,
.button-secondary:focus {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

.hero-strip {
  align-self: end;
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  max-width: 880px;
}

.hero-point {
  border-left: 3px solid #f5b642;
  color: rgba(255, 255, 255, 0.88);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.45;
  padding-left: 12px;
}

.main-frame {
  display: grid;
  gap: 30px;
  grid-template-columns: minmax(0, 1fr) 330px;
  margin: 0 auto;
  max-width: 1180px;
  padding: 36px 22px 0;
}

.content-column,
.sidebar {
  min-width: 0;
}

.feed-toolbar {
  align-items: end;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 18px;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 18px;
}

.section-eyebrow {
  color: var(--red);
  display: block;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.14em;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(27px, 3vw, 38px);
  line-height: 1.12;
  margin: 0;
}

.feed-note {
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
  margin: 0;
  max-width: 260px;
  text-align: right;
}

.feed-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.post-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow-soft);
  display: flex;
  flex-direction: column;
  min-height: 100%;
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.post-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.post-thumb {
  aspect-ratio: 16 / 9;
  background: #dfe8e2;
  display: block;
  overflow: hidden;
  position: relative;
}

.post-thumb img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.thumb-placeholder {
  align-items: center;
  background:
    linear-gradient(135deg, rgba(15, 118, 110, 0.10), rgba(180, 35, 24, 0.08)),
    var(--surface-soft);
  color: var(--teal-dark);
  display: flex;
  font-family: var(--font-display);
  font-size: clamp(28px, 8vw, 56px);
  font-weight: 700;
  height: 100%;
  justify-content: center;
  letter-spacing: 0;
  width: 100%;
}

.post-card-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  padding: 18px;
}

.post-meta {
  align-items: center;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 12px;
  font-weight: 800;
  gap: 8px;
  line-height: 1.4;
  margin-bottom: 12px;
  text-transform: uppercase;
}

.label-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.label-pill {
  background: var(--surface-soft);
  border-radius: 999px;
  color: var(--teal-dark);
  display: inline-flex;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  padding: 7px 9px;
  text-transform: uppercase;
}

.label-pill:hover,
.label-pill:focus {
  background: var(--ink);
  color: #ffffff;
}

.post-card h2 {
  font-family: var(--font-display);
  font-size: 21px;
  line-height: 1.22;
  margin: 0 0 11px;
}

.post-card h2 a {
  color: var(--ink);
}

.post-card h2 a:hover,
.post-card h2 a:focus {
  color: var(--red);
}

.post-snippet {
  color: var(--ink-soft);
  display: -webkit-box;
  font-size: 14px;
  line-height: 1.6;
  margin: 0 0 18px;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.read-link {
  align-items: center;
  border-top: 1px solid var(--line);
  color: var(--teal-dark);
  display: flex;
  font-size: 13px;
  font-weight: 900;
  gap: 8px;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 14px;
}

.read-link:after {
  content: '->';
  font-size: 16px;
  line-height: 1;
}

.article-shell {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow-soft);
  overflow: hidden;
}

.article-header {
  background: linear-gradient(135deg, var(--surface-soft), #ffffff);
  border-bottom: 1px solid var(--line);
  padding: clamp(24px, 5vw, 48px);
}

.article-title {
  font-family: var(--font-display);
  font-size: clamp(31px, 5vw, 56px);
  letter-spacing: 0;
  line-height: 1.08;
  margin: 0;
  max-width: 860px;
}

.article-content {
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.85;
  overflow-wrap: break-word;
  padding: clamp(24px, 5vw, 50px);
}

.article-content p {
  margin: 0 0 1.25em;
}

.article-content h2,
.article-content h3,
.article-content h4 {
  color: var(--ink);
  font-family: var(--font-display);
  letter-spacing: 0;
  line-height: 1.2;
  margin: 1.6em 0 0.65em;
}

.article-content h2 {
  font-size: 30px;
}

.article-content h3 {
  font-size: 23px;
}

.article-content ul,
.article-content ol {
  margin: 0 0 1.35em 1.25em;
  padding: 0;
}

.article-content li {
  margin-bottom: 0.35em;
}

.article-content blockquote {
  background: var(--surface-warm);
  border-left: 4px solid var(--amber);
  margin: 1.5em 0;
  padding: 18px 20px;
}

.article-content table {
  border-collapse: collapse;
  display: block;
  margin: 1.5em 0;
  overflow-x: auto;
  width: 100%;
}

.article-content th,
.article-content td {
  border: 1px solid var(--line);
  padding: 10px 12px;
  text-align: left;
  vertical-align: top;
}

.article-content th {
  background: var(--surface-soft);
  font-weight: 900;
}

.article-content pre,
.article-content code {
  background: #f1f4f8;
  border-radius: 6px;
  font-family: Consolas, 'Fira Code', monospace;
}

.article-content code {
  padding: 2px 5px;
}

.article-content pre {
  overflow-x: auto;
  padding: 16px;
}

.article-content .hindi,
.article-content [lang='hi'] {
  font-family: var(--font-hindi);
}

.article-footer {
  align-items: center;
  background: var(--surface-soft);
  border-top: 1px solid var(--line);
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: space-between;
  padding: 18px clamp(24px, 5vw, 50px);
}

.article-footer a {
  font-size: 13px;
  font-weight: 900;
}

.blog-pager {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-top: 28px;
}

.blog-pager a {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow-soft);
  color: var(--ink);
  font-size: 13px;
  font-weight: 900;
  padding: 11px 15px;
}

.blog-pager a:hover,
.blog-pager a:focus {
  border-color: var(--teal);
  color: var(--teal-dark);
}

.sidebar {
  display: grid;
  gap: 18px;
  align-content: start;
}

.sidebar-layout-zone {
  display: grid;
  gap: 18px;
}

.widget-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow-soft);
  padding: 18px;
}

.widget-title {
  align-items: center;
  color: var(--ink);
  display: flex;
  font-size: 13px;
  font-weight: 900;
  gap: 10px;
  letter-spacing: 0.12em;
  margin: 0 0 15px;
  text-transform: uppercase;
}

.layout-widget-zone .widget-title,
.header-layout-zone .widget-title,
.wide-layout-zone .widget-title,
.post-layout-zone .widget-title,
.sidebar-layout-zone .widget-title,
#sidebar-extra .widget-title,
.footer-widget-zone .widget-title {
  align-items: center;
  color: inherit;
  display: flex;
  font-size: 13px;
  font-weight: 900;
  gap: 10px;
  letter-spacing: 0.12em;
  margin: 0 0 12px;
  text-transform: uppercase;
}

.widget-title:before {
  background: var(--red);
  content: '';
  display: inline-block;
  height: 12px;
  width: 12px;
}

.search-form {
  display: flex;
  gap: 8px;
}

.search-input {
  background: #f8faf9;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--ink);
  flex: 1 1 auto;
  font: inherit;
  font-size: 14px;
  min-width: 0;
  outline: none;
  padding: 11px 12px;
}

.search-input:focus {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.14);
}

.search-button {
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  color: #ffffff;
  cursor: pointer;
  flex: 0 0 auto;
  font-size: 13px;
  font-weight: 900;
  padding: 0 14px;
}

.search-button:hover,
.search-button:focus {
  background: var(--teal-dark);
}

.quick-list {
  display: grid;
  gap: 9px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.quick-list a {
  align-items: center;
  background: #f8faf9;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink-soft);
  display: flex;
  font-size: 13px;
  font-weight: 800;
  justify-content: space-between;
  line-height: 1.35;
  padding: 10px 12px;
}

.quick-list a:hover,
.quick-list a:focus {
  background: var(--surface-soft);
  border-color: var(--teal);
  color: var(--teal-dark);
}

.quick-list a:after {
  color: var(--red);
  content: '->';
  flex: 0 0 auto;
  margin-left: 8px;
}

.label-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.label-cloud a {
  align-items: center;
  background: var(--surface-soft);
  border-radius: 999px;
  color: var(--teal-dark);
  display: inline-flex;
  font-size: 12px;
  font-weight: 900;
  gap: 6px;
  padding: 7px 10px;
}

.label-count {
  background: #ffffff;
  border-radius: 999px;
  color: var(--muted);
  font-size: 11px;
  padding: 2px 6px;
}

.mini-note {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
  margin: 0;
}

.site-footer {
  background: var(--ink);
  color: rgba(255, 255, 255, 0.72);
  margin-top: 56px;
  padding: 38px 22px;
}

.footer-inner {
  display: grid;
  gap: 22px;
  margin: 0 auto;
  max-width: 1180px;
}

.footer-top {
  align-items: start;
  display: flex;
  gap: 24px;
  justify-content: space-between;
}

.footer-brand {
  color: #ffffff;
  font-family: var(--font-display);
  font-size: 24px;
  line-height: 1.2;
  margin: 0 0 8px;
}

.footer-copy {
  color: rgba(255, 255, 255, 0.68);
  font-size: 13px;
  margin: 0;
  max-width: 460px;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  justify-content: flex-end;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.74);
  font-size: 13px;
  font-weight: 800;
}

.footer-links a:hover,
.footer-links a:focus {
  color: #ffffff;
}

.footer-layout-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.footer-widget-zone .widget {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow: none;
  color: rgba(255, 255, 255, 0.78);
  margin: 0;
}

.footer-widget-zone a,
.footer-widget-zone .widget-title {
  color: #ffffff;
}

.copyright {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.55);
  font-size: 12px;
  margin: 0;
  padding-top: 18px;
}

.status-msg-wrap,
.blog-feeds,
.post-share-buttons,
.post-footer-line,
.feed-links {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

@media (max-width: 1020px) {
  .desktop-nav {
    display: none;
  }

  .header-layout-zone {
    display: none;
  }

  .nav-trigger,
  .mobile-nav {
    display: flex;
  }

  .mobile-nav {
    display: block;
  }

  .main-frame {
    grid-template-columns: 1fr;
  }

  .sidebar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .footer-layout-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .header-inner {
    min-height: 66px;
    padding: 10px 16px;
  }

  .brand-mark {
    flex-basis: 38px;
    height: 38px;
    width: 38px;
  }

  .brand-name {
    font-size: 17px;
  }

  .brand-tagline {
    display: none;
  }

  .mobile-nav {
    padding-left: 16px;
    padding-right: 16px;
    top: 66px;
  }

  .hero {
    min-height: 430px;
  }

  .hero-inner {
    padding: 42px 16px 28px;
  }

  .hero h1 {
    font-size: 38px;
  }

  .hero-summary {
    font-size: 16px;
  }

  .hero-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .main-frame {
    padding-left: 16px;
    padding-right: 16px;
  }

  .top-announcement,
  .below-hero-layout,
  .above-main-layout {
    padding-left: 16px;
    padding-right: 16px;
  }

  .feed-toolbar {
    align-items: start;
    display: grid;
  }

  .feed-note {
    max-width: none;
    text-align: left;
  }

  .feed-grid,
  .sidebar {
    grid-template-columns: 1fr;
  }

  .article-content {
    font-size: 16px;
  }

  .article-footer,
  .footer-top {
    display: grid;
  }

  .footer-links {
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .button {
    width: 100%;
  }

  .hero-strip {
    grid-template-columns: 1fr;
  }

  .search-form {
    display: grid;
  }

  .search-button {
    min-height: 42px;
  }
}

@media print {
  .site-header,
  .top-announcement,
  .site-footer,
  .sidebar,
  .hero-strip,
  .meta-strip,
  .search-form,
  .feed-toolbar,
  .skip-link,
  .menu-toggle,
  .menu-toggle-label,
  .nav-shell,
  .site-nav,
  .post-feeds,
  .blog-pager,
  .breadcrumbs,
  .share-buttons,
  .post-share-buttons,
  .related-posts,
  #comments,
  .comments,
  #ev-toc-bar,
  #ev-pdf-section,
  #ev-quiz-section,
  #evQBox,
  .evNav,
  .evScorecard,
  iframe,
  button {
    display: none !important;
  }

  body {
    background: #ffffff !important;
    color: #0f172a !important;
    font-size: 12pt !important;
    margin: 0 !important;
    padding: 0 !important;
  }

  .main-frame {
    display: block !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
  }

  .content-column,
  .post-article {
    border: none !important;
    box-shadow: none !important;
    background: transparent !important;
    padding: 0 !important;
  }

  article,
  .post-card,
  #ev-vocab-section > div,
  #ev-idioms-section,
  #ev-idioms-section > div > div,
  .ev-word-card,
  .ev-idiom-card,
  .ev-print-quiz {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    break-inside: avoid-page !important;
    margin-bottom: 14px !important;
  }

  .ev-print-quiz {
    display: block !important;
  }

  h1, h2, h3 {
    page-break-after: avoid !important;
    break-after: avoid !important;
  }
}

b:if.script:
//
  (function () {
    var path = window.location.pathname.replace(/\/+$/, '') || '/';
    var params = new URLSearchParams(window.location.search);
    var grid = document.querySelector('.feed-grid');
    var pager = document.querySelector('.blog-pager');
    var maxPosts = 12;
    var callbackName = 'editorialVocabRenderIndexFeed';

    if (!grid) {
      return;
    }

    function isIndexPage() {
      return path === '/' ||
        path === '/index.html' ||
        path.indexOf('/search') === 0 ||
        path.indexOf('/search/label/') === 0 ||
        path.indexOf('/search?') === 0;
    }

    if (!isIndexPage()) {
      return;
    }

    if (grid.querySelectorAll('.post-card').length > 1) {
      return;
    }

    grid.style.visibility = 'hidden';
    grid.style.minHeight = Math.max(grid.offsetHeight, 520) + 'px';

    function escapeHtml(value) {
      return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function stripHtml(value) {
      var holder = document.createElement('div');
      holder.innerHTML = value || '';
      return holder.textContent || holder.innerText || '';
    }

    function truncate(value, length) {
      var text = stripHtml(value).replace(/\s+/g, ' ').trim();
      if (text.length <= length) {
        return text;
      }
      return text.slice(0, length).replace(/\s+\S*$/, '') + '...';
    }

    function resizeBloggerImage(url) {
      return String(url || '')
        .replace(/\/s\d+(-c)?\//, '/s800/')
        .replace(/\/w\d+-h\d+[^/]*\//, '/s800/')
        .replace(/=s\d+(-c)?/, '=s800')
        .replace(/=w\d+-h\d+[^&]*/, '=s800');
    }

    function findImageInHtml(html) {
      var holder = document.createElement('div');
      var image;
      var styleMatch;
      holder.innerHTML = html || '';
      image = holder.querySelector('img[src]');

      if (image && image.getAttribute('src')) {
        return resizeBloggerImage(image.getAttribute('src'));
      }

      styleMatch = String(html || '').match(/url\((['"]?)(https?:\/\/[^'")]+)\1\)/i);
      return styleMatch ? resizeBloggerImage(styleMatch[2]) : '';
    }

    function getEntryText(entry) {
      if (entry.summary && entry.summary.$t) {
        return entry.summary.$t;
      }
      if (entry.content && entry.content.$t) {
        return entry.content.$t;
      }
      return '';
    }

    function getPostLink(entry) {
      var links = entry.link || [];
      for (var index = 0; index < links.length; index += 1) {
        if (links[index].rel === 'alternate') {
          return links[index].href;
        }
      }
      return '#';
    }

    function getPostImage(entry) {
      var thumbnail = entry.media$thumbnail && entry.media$thumbnail.url;
      if (thumbnail) {
        return resizeBloggerImage(thumbnail);
      }
      if (entry.content && entry.content.$t) {
        return findImageInHtml(entry.content.$t);
      }
      if (entry.summary && entry.summary.$t) {
        return findImageInHtml(entry.summary.$t);
      }
      return '';
    }

    function formatDate(entry) {
      var rawDate = entry.published && entry.published.$t;
      var date = rawDate ? new Date(rawDate) : null;
      if (!date || isNaN(date.getTime())) {
        return '';
      }
      return date.toLocaleDateString('en-IN', {
        weekday: 'long',
        day: '2-digit',
        month: 'long',
        year: 'numeric'
      });
    }

    function renderLabels(entry) {
      var categories = entry.category || [];
      var html = '';
      for (var index = 0; index < categories.length && index < 4; index += 1) {
        var label = categories[index].term || '';
        if (label) {
          html += '<a class="label-pill" href="/search/label/' + encodeURIComponent(label) + '">' + escapeHtml(label) + '</a>';
        }
      }
      return html ? '<div class="label-list">' + html + '</div>' : '';
    }

    function renderPost(entry) {
      var title = entry.title && entry.title.$t ? entry.title.$t : 'Untitled Lesson';
      var link = getPostLink(entry);
      var image = getPostImage(entry);
      var summary = getEntryText(entry);
      var date = formatDate(entry);
      var imageHtml = image
        ? '<img alt="' + escapeHtml(title) + '" loading="lazy" src="' + escapeHtml(image) + '"/>'
        : '<span class="thumb-placeholder">EV</span>';

      return [
        '<article class="post-card">',
          '<a class="post-thumb" href="' + escapeHtml(link) + '">',
            imageHtml,
          '</a>',
          '<div class="post-card-body">',
            '<div class="post-meta"><span>' + escapeHtml(date) + '</span></div>',
            renderLabels(entry),
            '<h2><a href="' + escapeHtml(link) + '">' + escapeHtml(title) + '</a></h2>',
            '<p class="post-snippet">' + escapeHtml(truncate(summary, 170)) + '</p>',
            '<a class="read-link" href="' + escapeHtml(link) + '">Read lesson</a>',
          '</div>',
        '</article>'
      ].join('');
    }

    function getFeedPath() {
      var labelPrefix = '/search/label/';
      var label;
      if (path.indexOf(labelPrefix) === 0) {
        label = decodeURIComponent(path.slice(labelPrefix.length));
        return '/feeds/posts/default/-/' + encodeURIComponent(label);
      }
      return '/feeds/posts/default';
    }

    function buildQuery() {
      var query = [
        'alt=json-in-script',
        'max-results=' + maxPosts,
        'callback=' + callbackName
      ];
      var updatedMax = params.get('updated-max');
      var searchQuery = params.get('q');

      if (updatedMax) {
        query.push('updated-max=' + encodeURIComponent(updatedMax));
      }
      if (searchQuery) {
        query.push('q=' + encodeURIComponent(searchQuery));
      }

      return query.join('&');
    }

    function buildOlderUrl(entries) {
      var last = entries[entries.length - 1];
      var updated = last && last.updated && last.updated.$t;
      var basePath = path.indexOf('/search/label/') === 0 ? path : '/search';
      var urlParams;

      if (!updated) {
        return '';
      }

      urlParams = new URLSearchParams();
      urlParams.set('updated-max', updated);
      urlParams.set('max-results', String(maxPosts));

      if (params.get('q')) {
        urlParams.set('q', params.get('q'));
      }

      return basePath + '?' + urlParams.toString();
    }

    function updatePager(entries) {
      var olderUrl = buildOlderUrl(entries);
      var newerLink;
      var olderLink;

      if (!pager || !olderUrl) {
        return;
      }

      newerLink = pager.querySelector('a[href*="updated-max"]');
      olderLink = pager.querySelector('a:last-child');

      if (path !== '/' && path !== '/index.html' && newerLink) {
        newerLink.setAttribute('href', '/');
      }

      if (olderLink) {
        olderLink.setAttribute('href', olderUrl);
      } else {
        pager.insertAdjacentHTML('beforeend', '<a href="' + escapeHtml(olderUrl) + '">Older posts</a>');
      }
    }

    window[callbackName] = function (json) {
      var entries = json && json.feed && json.feed.entry ? json.feed.entry : [];
      if (!entries.length) {
        grid.style.visibility = '';
        grid.style.minHeight = '';
        return;
      }

      grid.innerHTML = entries.map(renderPost).join('');
      grid.setAttribute('data-feed-source', 'blogger-default-feed');
      grid.style.visibility = '';
      grid.style.minHeight = '';
      updatePager(entries);
    };

    var script = document.createElement('script');
    script.src = getFeedPath() + '?' + buildQuery();
    document.body.appendChild(script);
  }());
//

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
